import{_ as e,o as l,c as a,a0 as d}from"./chunks/framework.DqMqoJl9.js";const o=JSON.parse('{"title":"服务管理","description":"","frontmatter":{},"headers":[],"relativePath":"linux/service.md","filePath":"linux/service.md","lastUpdated":1791042271000}'),s={name:"linux/service.md"};function n(i,t,r,y,x,g){return l(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="服务管理" tabindex="-1">服务管理 <a class="header-anchor" href="#服务管理" aria-label="Permalink to &quot;服务管理&quot;">​</a></h1><h2 id="运行级别" tabindex="-1">运行级别 <a class="header-anchor" href="#运行级别" aria-label="Permalink to &quot;运行级别&quot;">​</a></h2><ul><li><code>0</code> 关机</li><li><code>1</code> 单用户模式，可以想象为windows的安全模式，主要用于系统修复</li><li><code>2</code> 不完全的命令行模式，不含NFS服务</li><li><code>3</code> 完全的命令行模式，就是标准字符界面</li><li><code>4</code> 系统保留</li><li><code>5</code> 图形模式</li><li><code>6</code> 重启</li></ul><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">runlevel            </span><span style="color:#6A737D;">// 查看当前运行级别</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">init [运行级别]     </span><span style="color:#6A737D;">// 修改运行级别</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">/</span><span style="color:#24292E;">etc</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">inittab        </span><span style="color:#6A737D;">// 修改默认运行级别配置文件</span></span>
<span class="line"><span style="color:#D73A49;">-</span><span style="color:#6F42C1;"> id</span><span style="color:#24292E;">:</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">:</span><span style="color:#6F42C1;">initdefault</span><span style="color:#24292E;">:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="服务分类" tabindex="-1">服务分类 <a class="header-anchor" href="#服务分类" aria-label="Permalink to &quot;服务分类&quot;">​</a></h2><ul><li>RPM包默认安装的服务 <ul><li>独立的服务（系统大多的服务都是独立服务）</li><li>基于xinetd服务（超级守护进程，用于管理一些后台程序）（逐渐淘汰）</li></ul></li><li>源码包安装的服务</li></ul><p>linux服务分为以上两种服务，不同的安装方式服务管理不一样</p><h2 id="服务管理-1" tabindex="-1">服务管理 <a class="header-anchor" href="#服务管理-1" aria-label="Permalink to &quot;服务管理&quot;">​</a></h2><h3 id="systemctl" tabindex="-1">systemctl <a class="header-anchor" href="#systemctl" aria-label="Permalink to &quot;systemctl&quot;">​</a></h3><p>systemctl命令是系统服务管理器指令，它实际上将 service 和 chkconfig 这两个命令组合到一起</p><table tabindex="0"><thead><tr><th style="text-align:left;">任务</th><th style="text-align:left;">旧指令</th><th style="text-align:left;">新指令</th></tr></thead><tbody><tr><td style="text-align:left;">使某服务自动启动</td><td style="text-align:left;">chkconfig --level 3 httpd on</td><td style="text-align:left;">systemctl enable httpd.service</td></tr><tr><td style="text-align:left;">使某服务不自动启动</td><td style="text-align:left;">chkconfig --level 3 httpd off</td><td style="text-align:left;">systemctl disable httpd.service</td></tr><tr><td style="text-align:left;">检查服务状态</td><td style="text-align:left;">service httpd status</td><td style="text-align:left;">systemctl status httpd.service</td></tr><tr><td style="text-align:left;">显示所有已启动的服务</td><td style="text-align:left;">chkconfig --list</td><td style="text-align:left;">systemctl list-units --type=service</td></tr><tr><td style="text-align:left;">启动某服务</td><td style="text-align:left;">service httpd start</td><td style="text-align:left;">systemctl start httpd.service</td></tr><tr><td style="text-align:left;">停止某服务</td><td style="text-align:left;">service httpd stop</td><td style="text-align:left;">systemctl stop httpd.service</td></tr><tr><td style="text-align:left;">重启某服务</td><td style="text-align:left;">service httpd restart</td><td style="text-align:left;">systemctl restart httpd.service</td></tr></tbody></table><h3 id="etc-init-d" tabindex="-1">/etc/init.d/ <a class="header-anchor" href="#etc-init-d" aria-label="Permalink to &quot;/etc/init.d/&quot;">​</a></h3><p>常规的服务管理方式，所有linux系统都支持</p><p>/etc/init.d/ 目录下存放的是服务的shell脚本，可以直接用了管理服务</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">/</span><span style="color:#24292E;">etc</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">init.d</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">[独立的服务名] start</span><span style="color:#D73A49;">|</span><span style="color:#24292E;">stop</span><span style="color:#D73A49;">|</span><span style="color:#24292E;">status</span><span style="color:#D73A49;">|</span><span style="color:#24292E;">restart</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="etc-rc-d-rc-local-自启动配置文件" tabindex="-1">/etc/rc.d/rc.local 自启动配置文件 <a class="header-anchor" href="#etc-rc-d-rc-local-自启动配置文件" aria-label="Permalink to &quot;/etc/rc.d/rc.local 自启动配置文件&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 在文件中加入</span></span>
<span class="line"><span style="color:#D73A49;">/</span><span style="color:#24292E;">etc</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">init.d</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">httpd start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p>两种自启动方式是独立的，同时设置会冲突</p></div><h2 id="通过端口查看服务" tabindex="-1">通过端口查看服务 <a class="header-anchor" href="#通过端口查看服务" aria-label="Permalink to &quot;通过端口查看服务&quot;">​</a></h2><p>查看正在使用的端口，会列出系统中所有已启动的服务</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">netstat </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">tlunp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>-t</code> 列出tcp数据</li><li><code>-u</code> 列出udp数据</li><li><code>-l</code> 列出正在监听的网络服务（不包含已经连接的网络服务）</li><li><code>-n</code> 用端口号来显示服务，而不是用服务名</li><li><code>-p</code> 列出改服务的进程（PID）</li></ul><h2 id="linux服务列表" tabindex="-1">linux服务列表 <a class="header-anchor" href="#linux服务列表" aria-label="Permalink to &quot;linux服务列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">服务名称</th><th style="text-align:left;">功能简介</th><th style="text-align:left;">建议</th></tr></thead><tbody><tr><td style="text-align:left;">acpid</td><td style="text-align:left;">电源管理接口。如果是笔记本用户建议开启，可以监听内核层的相关电源事件</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">anacron</td><td style="text-align:left;">系统的定时任务程序。cron 的一个子系统，如果定时任务错过了执行时间，可以通过 anacron 继续唤醒执行</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">alsasound</td><td style="text-align:left;">Alsa 声卡驱动。如果使用 alsa 声卡，开启</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">apmd</td><td style="text-align:left;">电源管理模块。如果支持 acpid，就不需要 apmd，可以关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">atd</td><td style="text-align:left;">指定系统在特定时间执行某个任务，只能执行一次。如果需要则开启，但我们一般使用 crond 来进行循环定时任务</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">auditd</td><td style="text-align:left;">审核子系统。如果开启了此服务，SELinux 的审核信息会写入/var/log/audit/audit.log 文件，如果不开启，审核信息会记录在 syslog 中</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">autofs</td><td style="text-align:left;">让服务器可以自动挂载网络中的其他服务器的共享数据，一般用来自动挂载 NFS 服务。如果没有 NFS 服务建议关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">avahi-daemon</td><td style="text-align:left;">Avahi 是 zeroconf 协议的实现。它可以在没有 DNS 服务的局域网里发现基于 zeroconf 协议的设备和服务。除非有兼容设备或使用 zeroconf 协议，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">bluetooth</td><td style="text-align:left;">蓝牙设备支持。一般不会在服务器上启用蓝牙设备，关闭它</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">capi</td><td style="text-align:left;">仅对使用 ISND 设备的用户有用</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">chargen-dgram</td><td style="text-align:left;">使用 UDP 协议的 chargen server。主要功能是提供类似远程打字的功能</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">chargen-stream</td><td style="text-align:left;">同上</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">cpuspeed</td><td style="text-align:left;">可以用来调整 CPU 的频率。当闲置时可以自动降低 CPU 频率来节省电量</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">crond</td><td style="text-align:left;">系统的定时任务，一般的 Linux 服务器都需要定时任务帮助系统维护。建议开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">cvs</td><td style="text-align:left;">一个版本控制系统</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">daytime-dgram</td><td style="text-align:left;">daytime 使用 TCP 协议的 Daytime 守护进程，该协议为客户机实现从远程服务器获取日期 和时间的功能</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">daytime-stream</td><td style="text-align:left;">同上</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">dovecot</td><td style="text-align:left;">邮件服务中 POP3/IMAP 服务的守护进程。主要用来接收信件，如果启动了邮件服务则开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">echo-dgram</td><td style="text-align:left;">服务器回显客户服务的进程</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">echo-stream</td><td style="text-align:left;">同上</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">firstboot</td><td style="text-align:left;">系统安装完成之后，有个欢迎界面，需要对系统进程初始设定。就是这个进程的作用</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">gpm</td><td style="text-align:left;">在字符终端（tty1-tty6）中可以使用鼠标复制和粘贴。就是这个服务的功能</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">haldaemon</td><td style="text-align:left;">检测盒支持 USB 设备。如果是服务器可以关闭，个人机建议开启</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">hidd</td><td style="text-align:left;">蓝牙鼠标、键盘等蓝牙设备检测。必须启动 bluetooth 服务</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">hplip</td><td style="text-align:left;">HP 打印机支持，如果没有 HP 打印机关闭吧</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">httpd</td><td style="text-align:left;">apache 服务的守护进程。如果需要启动 apache，就开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">ip6tables</td><td style="text-align:left;">IPv6 的防火墙，目前 IPv6 协议并没有使用，可以关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">iptables</td><td style="text-align:left;">防火墙功能，Linux 中防火墙是内核支持功能。这是服务器的主要防护手段，必须开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">irda</td><td style="text-align:left;">IrDA 提供红外线设备（笔记本，PDA’s，手机，计算器等等）间的通讯支持</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">irqbalance</td><td style="text-align:left;">支持多核处理器，让 CPU 可以自动分配系统中断（IRQ），提高系统性能。目前服务器多是多核 CPU，请开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">isdn</td><td style="text-align:left;">使用 ISDN 设备连接网络。目前主流的联网方式是光纤接入和ADSL，ISDN 已经非常少见，请关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">kudzu</td><td style="text-align:left;">该服务可以在开机时进行硬件检测，并会调用相关的设置软件。建议关闭，仅在需要时开启</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">lvm2-monitor</td><td style="text-align:left;">该服务可以让系统支持 LVM 逻辑卷组，如果分区采用的是 LVM方式，那么应该开启。建议开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">mcstrans</td><td style="text-align:left;">SELinux 的支持服务。建议启动</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">mdmonitor</td><td style="text-align:left;">该服务用来监测 Software RAID 或 LVM 的信息。不是必须服务，建议关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">mdmpd</td><td style="text-align:left;">该服务用来监测 Multi-Path 设备。不是必须服务</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">messagebus</td><td style="text-align:left;">这是 Linux 的 IPC（Interprocess Communication，进程间通讯）服务，用来在各个软件中交换信息</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">microcode_ctl</td><td style="text-align:left;">Intel 系列的 CPU 可以通过这个服务支持额外的微指令集</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">mysqld</td><td style="text-align:left;">mysql 数据库服务器。如果需要就开启，否则关闭</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">named</td><td style="text-align:left;">DNS 服务的守护进程，用来进行域名解析。如果是 DNS 服务器则开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">netfs</td><td style="text-align:left;">该服务用于在系统启动时自动挂载网络中的共享文件空间，比如：NFS，Samba 等等。需要就开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">network</td><td style="text-align:left;">提供网络设置功能。通过这个服务来管理网络，所以开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">nfs</td><td style="text-align:left;">NFS（Network File System）服务，Linux 与 Linux 之间的文件共享服务。需要就开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">nfslock</td><td style="text-align:left;">在 Linux 中如果使用了 NFS 服务，为了避免同一个文件被不同的用户同时编辑，所有有这个锁服务。有 NFS 是开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">ntpd</td><td style="text-align:left;">该服务可以通过互联网自动更新系统时间，使系统时间永远都准确。需要则开启，但不是必须服务</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">pcscd</td><td style="text-align:left;">智能卡检测服务，可以关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">portmap</td><td style="text-align:left;">用在远程过程调用（RPC）的服务，如果没有任何 RPC 服务时，可以关闭。主要是 NFS 和 NIS 服务需要</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">psacct</td><td style="text-align:left;">该守护进程支持几个监控进程活动的工具</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">rdisc</td><td style="text-align:left;">客户端 ICMP 路由协议</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">readahead_early</td><td style="text-align:left;">在系统开机的时候，先将某些进程加载如内存整理，可以加快一点启动速度</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">readahead_later</td><td style="text-align:left;">同上</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">restorecond</td><td style="text-align:left;">用于给 SELinux 监测和重新加载正确的文件上下文。如果开启 SELinux 则需要开启</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">rpcgssd</td><td style="text-align:left;">与 NFS 有关的客户端功能。如果没有 NFS 就关闭吧</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">rpcidmapd</td><td style="text-align:left;">同上</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">rsync</td><td style="text-align:left;">远程数据备份守护进程</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">sendmail</td><td style="text-align:left;">sendmail 邮件服务的守护进程。如果有邮件服务就开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">setroubleshoot</td><td style="text-align:left;">该服务用于将 SELinux 相关信息记录在日志/var/log/messages 中。建议开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">smartd</td><td style="text-align:left;">该服务用于自动检测硬盘状态。建议开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">smb</td><td style="text-align:left;">网络服务 samba 的守护进程。可以让 Linux 和 Windows 之间共享数据。如果需要则开启</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">squid</td><td style="text-align:left;">代理服务的守护进程。如果需要则开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">sshd</td><td style="text-align:left;">ssh 加密远程登陆管理的服务。服务器的远程管理必须使用此服务，不要关闭</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">syslog</td><td style="text-align:left;">日志的守护进程</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">vsftpd</td><td style="text-align:left;">vsftp 服务的守护进程。如果需要 FTP 服务则开启，否则关闭</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">xfs</td><td style="text-align:left;">这个是 X Window 的字体守护进程。为图形界面提供字体服务，如果不启动图形界面，就不用开启</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">xinetd</td><td style="text-align:left;">超级守护进程。如果有依赖 xinetd 的服务就必须开启</td><td style="text-align:left;">开启</td></tr><tr><td style="text-align:left;">ypbind</td><td style="text-align:left;">为 NIS（网络信息系统）客户机激活 ypbind 服务进程</td><td style="text-align:left;">关闭</td></tr><tr><td style="text-align:left;">yum-updatesd</td><td style="text-align:left;">yum 的在线升级服务</td><td style="text-align:left;">关闭</td></tr></tbody></table>`,24)])])}const c=e(s,[["render",n]]);export{o as __pageData,c as default};
